    fn unicode_control_glyph(code: u32) -> char {
        if code < 32 {
            let from_table = Self::unicode_control_glyphs()[code as usize];
            let from_pictures = Self::control_picture(code as u8);
            if from_table == from_pictures {
                from_pictures
            } else {
                from_table
            }
        } else if code == 127 {
            Self::control_picture(0x7F)
        } else {
            Self::unicode_control_strings()[32]
        }
    }

    fn render_c0_control(code: u32, notation: NonprintableNotation) -> String {
        match notation {
            NonprintableNotation::Caret => Self::render_c0_caret(code),
            NonprintableNotation::Unicode => Self::unicode_control_glyph(code).to_string(),
        }
    }

    fn render_delete(notation: NonprintableNotation) -> String {
        match notation {
            NonprintableNotation::Caret => String::from("^?"),
            NonprintableNotation::Unicode => '\u{2421}'.to_string(),
        }
    }

    fn render_line_feed(notation: NonprintableNotation) -> String {
        match notation {
            NonprintableNotation::Caret => String::from("^J\n"),
            NonprintableNotation::Unicode => String::from("␊\n"),
        }
    }

