fn get_header_component_indent_length(&self) -> usize {
    if self.config.style_components.grid() && self.panel_width > 0 {
        self.panel_width + 2
    } else {
        self.panel_width
    }
}

fn print_header_component_indent(&mut self, handle: &mut OutputHandle) -> Result<()> {
    if self.config.style_components.grid() {
        write!(
            handle,
            "{}{}",
            Self::header_indent_spaces(self.panel_width),
            self.colors
                .grid
                .paint(Self::header_grid_prefix(self.panel_width)),
        )
    } else {
        write!(handle, "{}", Self::header_indent_spaces(self.panel_width))
    }
}

fn print_header_component_with_indent(
    &mut self,
    handle: &mut OutputHandle,
    content: &str,
) -> Result<()> {
    self.print_header_component_indent(handle)?;
    writeln!(handle, "{}", content)
}

fn print_header_multiline_component(
    &mut self,
    handle: &mut OutputHandle,
    content: &str,
) -> Result<()> {
    let mut remaining = content;
    let content_width = self.config.term_width - self.get_header_component_indent_length();
    while remaining.chars().count() > content_width {
        let split_idx = remaining
            .char_indices()
            .nth(content_width)
            .map(|(idx, _)| idx)
            .unwrap_or(remaining.len());
        let (content_line, rest) = remaining.split_at(split_idx);
        self.print_header_component_with_indent(handle, content_line)?;
        remaining = rest;
    }
    self.print_header_component_with_indent(handle, remaining)
}

